// aim.cpp
// Projects entity head positions to screen space, picks the target closest to the
// screen centre within a pixel-radius cone, and returns a smoothed crosshair delta.
//
// Pure math module: no process access, no input injection. The caller supplies the
// view-projection matrix, head positions and viewport size, and decides what to do
// with the returned delta (e.g. drive a trainer's on-screen guide or bot crosshair).
//
// Matrix convention: row-major, column-vector multiply (clip = M * [x y z 1]^T),
// i.e. the D3D "ViewProj" transposed form most engines expose. If your matrix is
// the other layout, set AimParams::transposed = true.
//
// Build (MSVC):  cl /std:c++17 /EHsc /O2 /DAIM_SMOKE aim.cpp
// Build (clang): clang++ -std=c++17 -O2 -DAIM_SMOKE aim.cpp -o aim

#include <cmath>
#include <cstddef>
#include <cstdio>
#include <limits>

namespace aim {

struct Vec2 { float x = 0.f, y = 0.f; };
struct Vec3 { float x = 0.f, y = 0.f, z = 0.f; };
struct Mat4 { float m[4][4] = {}; };

struct AimParams {
    float fovRadiusPx   = 240.f;  // cone radius around screen centre, in pixels
    float smoothing     = 0.25f;  // fraction of remaining offset applied per tick (0..1]
    float blend         = 0.5f;   // EMA weight of new delta vs previous delta (0..1]
    float maxStepPx     = 40.f;   // clamp on per-tick delta magnitude (<=0 disables)
    float stickyBonusPx = 30.f;   // hysteresis: current target treated as this much closer
    float deadzonePx    = 0.5f;   // offsets smaller than this produce zero delta
    float minClipW      = 0.01f;  // reject points behind/at the near plane
    bool  transposed    = false;  // matrix stored row-vector style
};

struct AimState {
    Vec2 lastDelta{};
    int  targetIndex = -1;
};

struct AimResult {
    bool  hasTarget   = false;
    int   targetIndex = -1;
    Vec2  targetScreen{};   // projected head position, pixels
    Vec2  rawOffset{};      // target - centre, pixels
    Vec2  delta{};          // smoothed crosshair delta to apply this tick, pixels
    float distancePx  = 0.f;
};

static inline float Clamp01(float v) { return v < 0.f ? 0.f : (v > 1.f ? 1.f : v); }

static inline float At(const Mat4& M, int r, int c, bool transposed) {
    return transposed ? M.m[c][r] : M.m[r][c];
}

// Projects a world-space point to pixel coordinates. Returns false if the point is
// behind the camera or outside the clip volume in x/y.
bool WorldToScreen(const Mat4& M, const Vec3& p, int width, int height,
                   Vec2* out, const AimParams& prm) {
    const bool t = prm.transposed;
    float cx = At(M,0,0,t)*p.x + At(M,0,1,t)*p.y + At(M,0,2,t)*p.z + At(M,0,3,t);
    float cy = At(M,1,0,t)*p.x + At(M,1,1,t)*p.y + At(M,1,2,t)*p.z + At(M,1,3,t);
    float cw = At(M,3,0,t)*p.x + At(M,3,1,t)*p.y + At(M,3,2,t)*p.z + At(M,3,3,t);
    if (cw < prm.minClipW) return false;

    float ndcX = cx / cw;
    float ndcY = cy / cw;
    if (ndcX < -1.f || ndcX > 1.f || ndcY < -1.f || ndcY > 1.f) return false;

    out->x = (ndcX * 0.5f + 0.5f) * static_cast<float>(width);
    out->y = (1.f - (ndcY * 0.5f + 0.5f)) * static_cast<float>(height);
    return true;
}

// Selects the head closest to screen centre inside the cone (with hysteresis toward
// the previous target) and returns a smoothed, clamped delta toward it.
AimResult ComputeAimDelta(const Mat4& viewProj, const Vec3* heads, std::size_t count,
                          int width, int height, const AimParams& prm, AimState* state) {
    AimResult res;
    const Vec2 centre{ width * 0.5f, height * 0.5f };
    const float r2 = prm.fovRadiusPx * prm.fovRadiusPx;

    float bestScore = std::numeric_limits<float>::max();
    for (std::size_t i = 0; i < count; ++i) {
        Vec2 s;
        if (!WorldToScreen(viewProj, heads[i], width, height, &s, prm)) continue;
        float dx = s.x - centre.x, dy = s.y - centre.y;
        float d2 = dx*dx + dy*dy;
        if (d2 > r2) continue;

        float d = std::sqrt(d2);
        float score = d;
        if (state && static_cast<int>(i) == state->targetIndex)
            score -= prm.stickyBonusPx;
        if (score < bestScore) {
            bestScore        = score;
            res.hasTarget    = true;
            res.targetIndex  = static_cast<int>(i);
            res.targetScreen = s;
            res.rawOffset    = { dx, dy };
            res.distancePx   = d;
        }
    }

    if (!res.hasTarget) {
        if (state) { state->targetIndex = -1; state->lastDelta = {}; }
        return res;
    }

    Vec2 want{};
    if (res.distancePx > prm.deadzonePx) {
        float k = Clamp01(prm.smoothing);
        want = { res.rawOffset.x * k, res.rawOffset.y * k };
    }

    Vec2 prev = (state && state->targetIndex == res.targetIndex) ? state->lastDelta : Vec2{};
    float b = Clamp01(prm.blend);
    Vec2 d{ prev.x + (want.x - prev.x) * b, prev.y + (want.y - prev.y) * b };

    // Never overshoot the remaining offset.
    if (std::fabs(d.x) > std::fabs(res.rawOffset.x)) d.x = res.rawOffset.x;
    if (std::fabs(d.y) > std::fabs(res.rawOffset.y)) d.y = res.rawOffset.y;

    if (prm.maxStepPx > 0.f) {
        float mag = std::sqrt(d.x*d.x + d.y*d.y);
        if (mag > prm.maxStepPx) {
            float s = prm.maxStepPx / mag;
            d.x *= s; d.y *= s;
        }
    }

    res.delta = d;
    if (state) { state->lastDelta = d; state->targetIndex = res.targetIndex; }
    return res;
}

// Simple perspective * identity-view matrix for testing (camera at origin, +Z forward).
Mat4 MakePerspective(float fovYRad, float aspect, float zn, float zf) {
    Mat4 M;
    float f = 1.f / std::tan(fovYRad * 0.5f);
    M.m[0][0] = f / aspect;
    M.m[1][1] = f;
    M.m[2][2] = zf / (zf - zn);
    M.m[2][3] = -zn * zf / (zf - zn);
    M.m[3][2] = 1.f;
    return M;
}

} // namespace aim

#ifdef AIM_SMOKE
int main() {
    using namespace aim;
    const int W = 1920, H = 1080;
    Mat4 vp = MakePerspective(1.2f, float(W) / H, 0.1f, 1000.f);

    Vec3 heads[] = {
        {  0.6f, 0.3f, 10.f },  // near centre
        {  8.0f, 0.0f, 10.f },  // outside cone
        {  0.0f, 0.0f, -5.f },  // behind camera
    };

    AimParams prm;
    AimState  st;
    for (int tick = 0; tick < 5; ++tick) {
        AimResult r = ComputeAimDelta(vp, heads, 3, W, H, prm, &st);
        std::printf("tick %d: target=%d dist=%.1f delta=(%.2f, %.2f)\n",
                    tick, r.targetIndex, r.distancePx, r.delta.x, r.delta.y);
    }
    return 0;
}
#endif
